432			t.Fatalf("unknown request: got %v", err)
433		}
434		if _, err := s.RequestHistory("rMissing"); !errors.Is(err, ErrNotFound) {
435			t.Fatalf("unknown request history: got %v, want ErrNotFound", err)
436		}
437	}
