	if requestID == "" {
		return
	}
	if _, ok := s.requests[requestID]; !ok {
		return
	}
	s.appendHistoryLocked(requestID, HistoryRecord{
		CommitID: commitID,
		PartID:   partID,
		Quantity: quantity,
		Expiry:   expiry,
		Now:      now,
		Error:    HistoryErrorInvalidParam,
	})
}

